head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.select_yyyy = ''; // 선택한 연도
scwin.past_1yyyy = ''; // 선택한 연도의 1년전 연도
scwin.past_2yyyy = ''; // 선택한 연도의 2년전 연도
scwin.past_3yyyy = ''; // 선택한 연도의 3년전 연도
scwin.past_4yyyy = '';

// 화면명

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF25950.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF25950.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        // 조회를 성공하면 선택한 년도를 헤더에 그려준다.
        let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
        let date = new Date();
        date.setFullYear(parseInt(year));
        scwin.select_yyyy = year; // 현재연도
        scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
        scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
        scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
        scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도

        // 헤더에 현재 연도~4년전 연도를 표시
        $c.cm.setColumnProp(grd_Grid, 'Y', 'Name', 'Y (' + scwin.select_yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_1', 'Name', 'Y-1 (' + scwin.past_1yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_2', 'Name', 'Y-2 (' + scwin.past_2yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_3', 'Name', 'Y-3 (' + scwin.past_3yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_4', 'Name', 'Y-4 (' + scwin.past_4yyyy + '년)');
        // FillGridHeaderTotalCnt(rowcount, panel_page);    //총 건수
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25950.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_year_OnLoadCompleted
 * @description dts_year 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_year_OnLoadCompleted = function(rowcount) {
    try {
        // 연도가 없다는건 실제 데이타가 없다는 것이기 때문에 별도 텍스트를 보여줌
        if (rowcount === 0) {
            dts_year.insertRow();
            dts_year.setCellData(1, "YEAR_TEXT", '연도가 존재하지 않습니다');
            dts_year.setCellData(1, "YEAR", '');
        } else {
            // 연도가 있을 경우 헤더에 default로 최근 연도를 표시
            let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
            let date = new Date();
            date.setFullYear(parseInt(year));
            scwin.select_yyyy = year; // 현재연도
            scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
            scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
            scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
            scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도

            // 헤더에 현재 연도~4년전 연도를 표시
            $c.cm.setColumnProp(grd_Grid, 'Y', 'Name', 'Y (' + scwin.select_yyyy + '년)');
            $c.cm.setColumnProp(grd_Grid, 'Y_1', 'Name', 'Y-1 (' + scwin.past_1yyyy + '년)');
            $c.cm.setColumnProp(grd_Grid, 'Y_2', 'Name', 'Y-2 (' + scwin.past_2yyyy + '년)');
            $c.cm.setColumnProp(grd_Grid, 'Y_3', 'Name', 'Y-3 (' + scwin.past_3yyyy + '년)');
            $c.cm.setColumnProp(grd_Grid, 'Y_4', 'Name', 'Y-4 (' + scwin.past_4yyyy + '년)');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25950.dts_year_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_YearList_onselchange
 * @description cmb_YearList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_YearList_onselchange = function() {
    try {
        // 연도가 변경 되면 선택한 연도~4년전 연도를 셋팅
        let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
        let date = new Date();
        date.setFullYear(parseInt(year));
        scwin.select_yyyy = year; // 현재연도
        scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
        scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
        scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
        scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25950.cmb_YearList_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        scwin.excel();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25950.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setYear
 * @description 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setYear = async function() {
    // 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
    // ^temp 에서 temp는 의미 없는 값이지만, ^뒤에 데이타가 있어야 문구가 노출됨.
    cmb_YearList.CBData = "연도 조회중...^temp";

    // 연도조회(데이타가 등록 되어 있다면 연도가 조회 될 것이고 등록 안되어 있다면 연도가 없음)
    const sbmOptions = {
        id : "sbm_dts_year",
        action : "/EsgSearch.do",
        ref : "",
        target : "dts_year=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 연도 validation
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 연도 validation
    let year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex()); // 선택한 연도
    if (year === '') {
        await $c.win.alert("연도를 선택해주세요");
        return;
    }
    // 전체 기업 주요 정책ㆍ제도 시행현황(5개년) 통계 조회
    url += "&YEAR=" + year; // 선택한 연도
    url += "&PAST_1YEAR=" + scwin.past_1yyyy; // 선택한 연도에서 1년전 연도
    url += "&PAST_2YEAR=" + scwin.past_2yyyy; // 선택한 연도에서 2년전 연도
    url += "&PAST_3YEAR=" + scwin.past_3yyyy; // 선택한 연도에서 3년전 연도
    url += "&PAST_4YEAR=" + scwin.past_4yyyy; // 선택한 연도에서 4년전 연도

    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/EsgStatistics.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description 선택한 연도의 4년전 연도
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    await scwin.setYear();
};

/**
 * @method
 * @name excel
 * @description 엑셀 다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excel = function() {
    // 엑셀 다운로드
    $c.stf.doLogSave('ULDSTF25950.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_Grid, "전체 기업 주요 정책ㆍ제도 시행현황(5개년) 통계", "전체 기업 주요 정책ㆍ제도 시행현황(5개년) 통계.xlsx", "8", 0);
};
